const colors = {
  reset: "\x1b[0m",
  black: "\x1b[30m",
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  magenta: "\x1b[35m",
  cyan: "\x1b[36m",
  white: "\x1b[37m",
  gray: "\x1b[90m",
  brightRed: "\x1b[91m",
  brightGreen: "\x1b[92m",
  brightYellow: "\x1b[93m",
  brightBlue: "\x1b[94m",
  brightMagenta: "\x1b[95m",
  brightCyan: "\x1b[96m",
  brightWhite: "\x1b[97m"
};

function log(typeOrMessage, userOrColor, maybeMessage) {
  const time = new Date().toLocaleTimeString();
  const timestamp = `${colors.gray}[${time}]${colors.reset}`;
  let type = "info";
  let user = null;
  let message = "";
  if (maybeMessage !== undefined) {
    type = typeOrMessage;
    user = userOrColor;
    message = maybeMessage;
  }
  else if (colors[userOrColor]) {
    message = typeOrMessage;
    type = userOrColor;
  }
  else {
    message = typeOrMessage;
  }
  const colorMap = {
    yellow: "warn",
    red: "error",
    green: "success",
    cyan: "info",
    blue: "info",
    magenta: "command"
  };

  if (colorMap[type]) {
    type = colorMap[type];
  }

  let typeTag = "";
  if (type === "info") typeTag = `${colors.blue}INFO${colors.reset}`;
  else if (type === "success") typeTag = `${colors.green}SUCCESS${colors.reset}`;
  else if (type === "error") typeTag = `${colors.red}ERROR${colors.reset}`;
  else if (type === "warn") typeTag = `${colors.yellow}WARN${colors.reset}`;
  else if (type === "command") typeTag = `${colors.magenta}CMD${colors.reset}`;
  else typeTag = `${colors.white}LOG${colors.reset}`;

  const userTag = user
    ? `${colors.cyan}${user}${colors.reset}`
    : `${colors.yellow}SYSTEM${colors.reset}`;

  console.log(`${timestamp} | ${typeTag} | ${userTag} | ${message}`);
}

["info", "success", "error", "warn", "command"].forEach(type => {
  log[type] = (message, user = null) => log(type, user, message);
});

module.exports = { log };